import React, { useState, useEffect, useRef } from 'react';
import {
    Calendar,
    MapPin,
    Clock,
    Heart,
    ChevronDown,
    Music,
    Music2,
    Upload,
    Phone,
    Home,
    MailOpen,
    Menu,
    X
} from 'lucide-react';

function App() {
    const [activeTab, setActiveTab] = useState('home');
    const [isPlaying, setIsPlaying] = useState(false);
    const [overlayVisible, setOverlayVisible] = useState(true);
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [fade, setFade] = useState(true);
    const audioRef = useRef(null);

    /* =======================
       AUDIO FIX (IMPORTANT)
       ======================= */

    // Play / Pause when toggle changes
    useEffect(() => {
        const audio = audioRef.current;
        if (!audio) return;

        if (isPlaying) {
            audio.play().catch(() => {});
        } else {
            audio.pause();
        }
    }, [isPlaying]);

    // Stop audio when app goes to background / tab hidden
    useEffect(() => {
        const handleVisibilityChange = () => {
            const audio = audioRef.current;
            if (!audio) return;

            if (document.hidden) {
                audio.pause();
            } else if (isPlaying) {
                audio.play().catch(() => {});
            }
        };

        const stopAudio = () => {
            const audio = audioRef.current;
            if (!audio) return;
            audio.pause();
            audio.currentTime = 0;
        };

        document.addEventListener('visibilitychange', handleVisibilityChange);
        window.addEventListener('beforeunload', stopAudio);
        window.addEventListener('pagehide', stopAudio);

        return () => {
            document.removeEventListener('visibilitychange', handleVisibilityChange);
            window.removeEventListener('beforeunload', stopAudio);
            window.removeEventListener('pagehide', stopAudio);
        };
    }, [isPlaying]);

    /* =======================
       OVERLAY START AUDIO
       ======================= */
    const handleOverlayClick = () => {
        const audio = audioRef.current;
        if (!audio) return;

        audio.play().then(() => {
            setIsPlaying(true);
            setOverlayVisible(false);
        }).catch(() => {});
    };

    /* =======================
       UI HELPERS
       ======================= */
    const handleTabClick = (tab) => {
        setFade(false);
        setTimeout(() => {
            setActiveTab(tab);
            setFade(true);
        }, 150);
        setMobileMenuOpen(false);
    };

    const TabButton = ({ id, label, icon: Icon }) => (
        <button
            onClick={() => handleTabClick(id)}
            className={`flex items-center space-x-2 px-3 py-2 rounded-full transition-all duration-300 text-sm ${
                activeTab === id
                    ? 'bg-[#D4AF37] text-white'
                    : 'text-[#4A4238] hover:bg-[#D4AF37]/20'
            }`}
        >
            <Icon size={16} />
            <span className="uppercase tracking-widest font-bold">{label}</span>
        </button>
    );

    return (
        <div className="min-h-screen bg-[#FFFBF5] text-[#4A4238] font-serif relative">

            {/* AUDIO */}
            <audio ref={audioRef} src="/audio/fathiha.mp3" loop preload="auto" />

            {/* START AUDIO OVERLAY */}
            {overlayVisible && (
                <div
                    onClick={handleOverlayClick}
                    className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center text-white text-center cursor-pointer"
                >
                    <div>
                        <p className="text-3xl font-semibold">
                            Tap anywhere to start audio
                        </p>
                        <p className="text-sm mt-2 opacity-70">
                            Please allow audio to enjoy the experience
                        </p>
                    </div>
                </div>
            )}

            {/* NAVBAR */}
            <nav className="fixed top-0 w-full z-40 bg-white/70 backdrop-blur border-b border-[#D4AF37]/20 px-4 py-4">
                <div className="max-w-6xl mx-auto flex justify-between items-center">
                    <h2
                        className="text-xl italic cursor-pointer"
                        onClick={() => handleTabClick('home')}
                    >
                        <span className="shimmer-text">Shazeen</span>
                        <span className="mx-1 text-[#a6a6a6]">&</span>
                        <span className="shimmer-text">Shimra</span>
                    </h2>

                    <div className="hidden md:flex space-x-2">
                        <TabButton id="home" label="Home" icon={Home} />
                        <TabButton id="invitation" label="Invitation" icon={MailOpen} />
                        <TabButton id="rsvp" label="RSVP" icon={Heart} />
                        <TabButton id="location" label="Location" icon={MapPin} />
                    </div>

                    <div className="md:hidden">
                        <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)}>
                            {mobileMenuOpen ? <X /> : <Menu />}
                        </button>
                    </div>
                </div>
            </nav>

            {/* MUSIC TOGGLE BUTTON */}
            <button
                onClick={() => setIsPlaying(prev => !prev)}
                className="fixed bottom-6 right-6 w-16 h-16 bg-white/90 rounded-full shadow-2xl flex items-center justify-center text-[#D4AF37] z-40"
            >
                {isPlaying ? <Music2 className="animate-pulse" /> : <Music />}
                <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#D4AF37] rounded-full flex items-center justify-center text-[8px] text-white font-bold">
                    {isPlaying ? 'ON' : 'OFF'}
                </div>
            </button>

            {/* FOOTER */}
            <footer className="py-6 text-center text-xs tracking-widest opacity-40">
                &copy; 2026 Mohamed Shazeen. All Rights Reserved.
            </footer>

            {/* SHIMMER STYLE */}
            <style>{`
        .shimmer-text {
          background: linear-gradient(
            110deg,
            #b9922f 20%,
            #fff2b2 40%,
            #d4af37 60%,
            #b9922f 80%
          );
          background-size: 200% auto;
          -webkit-background-clip: text;
          color: transparent;
          animation: shimmer 3s linear infinite;
        }

        @keyframes shimmer {
          to {
            background-position: -200% center;
          }
        }
      `}</style>

        </div>
    );
}

export default App;
